import {
  IHikingJointlyEquipmentCreateDTO,
  IHikingJointlyEquipmentDTO,
  IHikingJointlyEquipmentMemberDTO,
  IHikingJointlyEquipmentUpdateDTO,
} from '../@types/DTO/hikingJointlyEquipment.dto.types';
import {
  IHikingJointlyEquipment,
  IHikingJointlyEquipmentMember,
} from '../@types/hikingJointlyEquipment.types';

const mapHikingJointlyEquipmentMemberToFront = (
  backData: IHikingJointlyEquipmentMemberDTO,
): IHikingJointlyEquipmentMember => {
  return {
    id: +backData.id,
    user: {
      id: +backData.id_user,
      name: backData.name,
      surname: backData.surname,
      photo: backData.photo_50,
    },
    comment: backData.comment,
    created_at: new Date(backData.created_at),
    date_from: backData.date_from ? new Date(backData.date_from) : null,
    date_to: backData.date_to ? new Date(backData.date_to) : null,
    id_author: +backData.id_author,
  };
};

export const mapHikingJointlyEquipmentToFront = (
  backData: IHikingJointlyEquipmentDTO,
): IHikingJointlyEquipment => {
  return {
    id: +backData.id,
    name: backData.name,
    comment: backData.comment,
    capacity: +backData.capacity,
    capacity_max: +backData.capacity_max,
    type: backData.type,

    author: {
      id: +backData.id_author,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
    created_at: new Date(backData.created_at),
    equip: backData.id_equip
      ? {
          id: +backData.id_equip,
          name: backData.equip_name,
          photo: backData.equip_photo,
          value: +backData.equip_value,
          weight: +backData.equip_weight,
          id_category: backData.equip_id_category ? +backData.equip_id_category : null,
          id_parent: backData.equip_id_parent ? +backData.equip_id_parent : null,
          is_archive: backData.equip_is_group == '1',
          is_group: backData.equip_is_group == '1',
          is_musthave: backData.equip_is_musthave == '1',
        }
      : null,
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    members: backData.members.map(mapHikingJointlyEquipmentMemberToFront),
  };
};

export const mapHikingJointlyEquipmentToAdd = (
  id_hiking: number,
  jointly_equipment: IHikingJointlyEquipment,
): IHikingJointlyEquipmentCreateDTO => {
  return {
    id_hiking,
    name: jointly_equipment.name,
    type: jointly_equipment.type,
    comment: jointly_equipment.comment,
    id_equip: jointly_equipment.equip?.id ?? null,
    capacity: jointly_equipment.capacity,
    capacity_max: jointly_equipment.capacity_max,
  };
};

export const mapHikingJointlyEquipmentToUpdate = (
  id_hiking: number,
  jointly_equipment: IHikingJointlyEquipment,
): IHikingJointlyEquipmentUpdateDTO => {
  return {
    id_hiking,
    id: jointly_equipment.id,
    name: jointly_equipment.name,
    comment: jointly_equipment.comment,
    id_equip: jointly_equipment.equip?.id ?? null,
  };
};
