import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingJointlyEquipmentToFront } from '../@mappers/hikingJointlyEquipment.mapper';
import {
  IHikingJointlyEquipmentCreateDTO,
  IHikingJointlyEquipmentDeleteDTO,
  IHikingJointlyEquipmentDTO,
  IHikingJointlyEquipmentMemberCreateDTO,
  IHikingJointlyEquipmentMemberDeleteDTO,
  IHikingJointlyEquipmentUpdateDTO,
} from '../@types/DTO/hikingJointlyEquipment.dto.types';
import { IHikingJointlyEquipment } from '../@types/hikingJointlyEquipment.types';
import { HikingJointlyEquipmentType } from './../@types/DTO/hikingJointlyEquipment.dto.types';

export const getHikingJointlyEquipments = async (
  id_hiking: number,
  type?: HikingJointlyEquipmentType,
): Promise<IHikingJointlyEquipment[]> => {
  const res = await get('/ajax/hiking/jointly_equipment/jointly_equipment_list.php', {
    id_hiking,
    type,
  }).then<IHikingJointlyEquipmentDTO[]>(handleApiError);
  return res.map(mapHikingJointlyEquipmentToFront);
};

export const addHikingJointlyEquipment = async (
  data: IHikingJointlyEquipmentCreateDTO,
): Promise<number> => {
  const res = await post('/ajax/hiking/jointly_equipment/jointly_equipment_add.php', data).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const editHikingJointlyEquipment = async (
  data: IHikingJointlyEquipmentUpdateDTO,
): Promise<boolean> => {
  const res = await post('/ajax/hiking/jointly_equipment/jointly_equipment_edit.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};

export const deleteHikingJointlyEquipment = async (
  data: IHikingJointlyEquipmentDeleteDTO,
): Promise<boolean> => {
  const res = await post('/ajax/hiking/jointly_equipment/jointly_equipment_del.php', data).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};

export const addHikingJointlyEquipmentMember = async (
  data: IHikingJointlyEquipmentMemberCreateDTO,
): Promise<number> => {
  const res = await post(
    '/ajax/hiking/jointly_equipment/jointly_equipment_member_add.php',
    data,
  ).then<{
    id: string;
  }>(handleApiError);
  return +res.id;
};

export const deleteHikingJointlyEquipmentMember = async (
  data: IHikingJointlyEquipmentMemberDeleteDTO,
): Promise<boolean> => {
  const res = await post(
    '/ajax/hiking/jointly_equipment/jointly_equipment_member_del.php',
    data,
  ).then<{
    success: string;
  }>(handleApiError);
  return Boolean(res?.success);
};
